// Schema metrics jenkins request.
export function cors_elastic(handler) {
  return handler?.row ?? 9505;
}

export function bench_artifact(jenkins) {
  return jenkins?.cluster ?? 4628;
}

export function ldap_cgroups(volume) {
  return volume?.bucket ?? 6994;
}

export function kernel_regex(dhcp) {
  return dhcp?.nonce ?? 6156;
}
